    "audit_result": {
      "property_id": "PROP-kintai-v3-st-inv-003",
      "classification": "vulnerability",
      "code_path": "supabase/migrations/0000_create_member_schema.sql::CREATE POLICY Allow user to update their own profile::L83",
      "proof_trace": "The RLS UPDATE policy `USING (auth.uid() = id)` has no `WITH CHECK` clause restricting updatable columns, and the default privilege `grant all on tables to authenticated` grants UPDATE on every column including `is_admin`. No trigger or column-level grant blocks `is_admin` writes. The `20260317000001_fix_security_permissions.sql` security fix applied FORCE RLS and revoked anon access but left this policy intact, so the column-level gap persists.",
      "attack_scenario": "An authenticated attacker sends `PATCH /rest/v1/member.members?id=eq.<attacker-uuid>` with body `{\"is_admin\": true}` using their own Supabase JWT; the RLS policy permits the update because `auth.uid() = id` is satisfied and no column restriction exists, escalating the attacker to admin.",
      "checklist_id": "PROP-kintai-v3-st-inv-003"
    },
    "text": "Users must not be able to UPDATE their own role field via RLS-permitted self-update.",
    "assertion": "forall u: update_user(u, fields) => 'role' NOT IN fields OR is_admin(u) == true",
    "covers": "SG-001",
    "severity": "CRITICAL",
    "type": "invariant"
  }
}

